'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['appendBatch']);
assert.strictEqual(typeof api.appendBatch, 'function');

const firstRef = { source: 'existing' };
const secondRef = { source: 'added' };
const existing = [firstRef, 'x', 'x'];
const added = [secondRef, 'y', 'x'];
const existingSnapshot = existing.slice();
const addedSnapshot = added.slice();
const result = api.appendBatch(existing, added);

assert.deepStrictEqual(result, [firstRef, 'x', 'x', secondRef, 'y', 'x']);
assert.strictEqual(result[0], firstRef);
assert.strictEqual(result[3], secondRef);
assert.notStrictEqual(result, existing);
assert.notStrictEqual(result, added);
assert.deepStrictEqual(existing, existingSnapshot);
assert.deepStrictEqual(added, addedSnapshot);

assert.deepStrictEqual(api.appendBatch([], []), []);
const emptyResult = api.appendBatch([], []);
assert.notStrictEqual(emptyResult, api.appendBatch([], []));
assert.deepStrictEqual(api.appendBatch([1, 2], []), [1, 2]);
assert.deepStrictEqual(api.appendBatch([], [3, 4]), [3, 4]);

const sparseExisting = [];
sparseExisting.length = 2;
sparseExisting[1] = 'existing';
const sparseAdded = [];
sparseAdded.length = 2;
sparseAdded[1] = 'added';
const sparseResult = api.appendBatch(sparseExisting, sparseAdded);
assert.deepStrictEqual(Array.from(sparseResult), [undefined, 'existing', undefined, 'added']);
assert.strictEqual(sparseResult.length, 4);
assert.strictEqual(sparseExisting.length, 2);
assert.strictEqual(sparseAdded.length, 2);

for (const args of [
  [null, []],
  [[], null],
  [{}, []],
  [[], {}],
  ['x', []],
  [[], 'x']
]) {
  assert.throws(() => api.appendBatch(...args), TypeError);
}

